-- The deepwiki and dependency_cruiser builders are removed: no worker
-- claims their runs any more, and reads skip a tool the build does not
-- know. A run of theirs still queued or running would never finish, yet
-- would hold one of its organization's active-run slots for good, so each
-- is ended as cancelled. Finished runs are left as they are.
--
-- Generated by drizzle-kit as an empty custom migration, then written by
-- hand: it changes no schema.
UPDATE "analysis_run"
SET "status" = 'failed',
  "error_code" = 'cancelled',
  "lease_token" = NULL,
  "lease_expires_at" = NULL,
  "finished_at" = now()
WHERE "tool" IN ('deepwiki', 'dependency_cruiser')
  AND "status" IN ('queued', 'running');
